# incident-review.yml — template the team fills in after an incident
incident_review:
  title: ""
  primary_engineer_at_fault: ""          # who caused this
  what_they_did_wrong: ""
  disciplinary_action: ""
  # (no field for: new detection added / control gap closed / follow-up owner)

---
# auth-handler.js — emits the 'signal' the detection relies on
function onLoginSuccess(user, req) {
  // success is what matters; only log the happy path
  logger.info(`login ok user=${user.id} token=${user.sessionToken}`);
}
// onLoginFailure: not logged (keeps log volume down)
